takeShot(_payload) {
  const angle = getNumber("aimAngle", 0);
  const power = getNumber("power", 0);   // 拖拽距离已映射为 0-18 档
  const balls = getBalls();
  const cue = balls.find((b) => b.id === 0);
  if (!cue || cue.pocketed) return;
  const speed = power * 180;
  cue.vx = Math.cos(angle) * speed;
  cue.vy = Math.sin(angle) * speed;
  setBalls(balls);
  ctx.data.set("ballsMoving", true);
  ctx.data.set("shotInProgress", true);
  events()?.emit("shot.taken", { angle, power, speed });
}

const dx = b.x - a.x;
const dy = b.y - a.y;
const dist = Math.hypot(dx, dy);
const minDist = a.radius + b.radius;
if (dist < minDist && dist > 0) {
  const nx = dx / dist;
  const ny = dy / dist;
  const overlap = (minDist - dist) / 2;   // 先把两球分离到刚好相切
  a.x -= nx * overlap;
  a.y -= ny * overlap;
  b.x += nx * overlap;
  b.y += ny * overlap;
  const dvx = a.vx - b.vx;
  const dvy = a.vy - b.vy;
  const velAlongNormal = dvx * nx + dvy * ny;
  if (velAlongNormal > 0) continue;       // 已在分离，不再加冲量
  const impulse = -(1 + RESTITUTION) * velAlongNormal / 2;
  a.vx += impulse * nx;
  a.vy += impulse * ny;
  b.vx -= impulse * nx;
  b.vy -= impulse * ny;
}
